-- Explicit grandfathering of pre-M8 tenants. Never used as a fallback for new tenants.
SELECT gen_random_uuid(),t.id,p.id,'ACTIVE','MANUAL',now(),now()+interval '1 month',now() FROM tenants t JOIN subscription_plans p ON p.code=CASE WHEN t.slug='construtora-demo' THEN 'PROFESSIONAL' ELSE 'LEGACY' END ON CONFLICT(tenant_id) DO NOTHING;
